class Solution {
    public int minPathSum(int[][] grid) {
        return costFrom(grid, 0, 0);
    }

    private int costFrom(int[][] grid, int row, int column) {
        int rows = grid.length;
        int columns = grid[0].length;
        if (row == rows - 1 && column == columns - 1) return grid[row][column];
        if (row == rows - 1) return grid[row][column] + costFrom(grid, row, column + 1);
        if (column == columns - 1) return grid[row][column] + costFrom(grid, row + 1, column);
        return grid[row][column] + Math.min(
                costFrom(grid, row + 1, column), costFrom(grid, row, column + 1));
    }
}

