class Solution {
    public int minPathSum(int[][] grid) {
        int rows = grid.length;
        int columns = grid[0].length;
        int[] best = new int[columns];
        for (int row = 0; row < rows; row++) {
            for (int column = 0; column < columns; column++) {
                if (row == 0 && column == 0) {
                    best[column] = grid[row][column];
                } else if (row == 0) {
                    best[column] = best[column - 1] + grid[row][column];
                } else if (column == 0) {
                    best[column] += grid[row][column];
                } else {
                    best[column] = Math.min(best[column], best[column - 1]) + grid[row][column];
                }
            }
        }
        return best[columns - 1];
    }
}
